    "theme": "La litanie des messagers rejetés — Moïse, Abraham, Noé, Hūd, Ṣāliḥ, Lot, Chuʿayb — chacun scandé du même refrain, et la distinction finale entre les poètes égarés et ceux qui croient",
    "note_pedagogique": "La grande sourate des récits prophétiques en cascade : sept prophètes, chacun clos par le même double refrain — « Il y a bien là un signe, mais la plupart ne sont pas croyants » et « Ton Seigneur, c'est Lui le Puissant, le Très-Miséricordieux ». La répétition martèle une loi de l'histoire. Elle se clôt sur les poètes (d'où son nom) : ceux qui « disent ce qu'ils ne font pas », distingués des poètes croyants.",
